{"path": "verify.mjs", "content": "import assert from 'node:assert/strict';
import { mergeRanges } from './ranges.mjs';

// public tests
assert.deepEqual(mergeRanges([[8, 10], [1, 3], [2, 5]]), [[1, 5], [8, 10]]);
assert.deepEqual(mergeRanges([[5, 7], [2, 4]]), [[2, 7]]);

// empty
assert.deepEqual(mergeRanges([]), []);

// contained interval must not shorten
assert.deepEqual(mergeRanges([[1, 10], [2, 3]]), [[1, 10]]);
assert.deepEqual(mergeRanges([[2, 3], [1, 10]]), [[1, 10]]);

// sort by start then end
assert.deepEqual(mergeRanges([[1, 5], [1, 3]]), [[1, 5]]);

// no mutation of input
const input = [[8, 10], [1, 3], [2, 5]];
const snapshot = JSON.parse(JSON.stringify(input));
const out = mergeRanges(input);
assert.deepEqual(input, snapshot);
assert.notEqual(out, input);
assert.notEqual(out[0], input[1]);

// fresh pairs
const a = [[1, 2]];
const r = mergeRanges(a);
assert.notEqual(r[0], a[0]);

// negative and touching
assert.deepEqual(mergeRanges([[-5, -3], [-2, 0]]), [[-5, 0]]);
assert.deepEqual(mergeRanges([[0, 0], [1, 1]]), [[0, 1]]);

// invalid inputs
for (const bad of [null, undefined, 5, 'x', {}, [[1]], [[1, 2, 3]], [[1.5, 2]], [[1, 2.5]], [[NaN, 2]], [[1, Infinity]], [[3, 1]], [['1', 2]], [[1, '2']], [[1, 2], [3]]]) {
  assert.throws(() => mergeRanges(bad), TypeError, `expected TypeError for ${JSON.stringify(bad)}`);
}

console.log('all checks passed');
"}

